306	    public String getSheetId() { return sheetId; }
307	    public String getName() { return name; }
308	    public void setName(String name) { this.name = name; }
309	    /** The first grade they were given: in force from the beginning of time, until their first dated grade. */
310	    public String getGrade() { return grade; }
311	    public void setGrade(String grade) { this.grade = grade; }
312	    /** Their own terms in days, ahead of their grade's and the sheet's; null when they have none. */
313	    public Integer getTerms() { return terms; }
314	    public void setTerms(Integer terms) { this.terms = terms; }
315	    /** The grades recorded from a date, by from-date: each in force from it until the next. */
316	    public Map<LocalDate, String> getDatedGrades() { return datedGrades; }
317	    /** Record the grade from this date, replacing any recorded from the same date. */
318	    public void setGradeFrom(String grade, LocalDate from) { datedGrades.put(from, grade); }
319	    /** The grade in force on the date: the latest dated one on or before it, else the first grade. */
320	    public String gradeOn(LocalDate date) {
321	        Map.Entry<LocalDate, String> dated = datedGrades.floorEntry(date);
322	        return dated == null ? grade : dated.getValue();
323	    }
