334	        this.statementCount = count;
335	        this.statedTotal = statedTotal;
336	        this.statementDate = statementDate;
337	    }
338	    /** The sheet's today when they were added; null when it was not kept (from the beginning of time). */
339	    public LocalDate getAddedOn() { return addedOn; }
340	    public void setAddedOn(LocalDate addedOn) { this.addedOn = addedOn; }
341	    /** Whether they had been added by the end of {@code day}. */
342	    public boolean addedBy(LocalDate day) { return addedOn == null || !addedOn.isAfter(day); }
343	    /** The date they are retired from; null when not retired. Set at all, they count as retired. */
344	    public LocalDate getRetiredFrom() { return retiredFrom; }
345	    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
346	    public boolean isRetired() { return retiredFrom != null; }
