392	public class ValidatePerson {
393	    private static final Set<String> GRADES = Set.of("A", "B", "C");
394	
395	    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body)
396	            throws InvalidPersonException {
397	        String name = PersonRequest.checkName(request == null ? null : request.name());
398	        String grade = request.grade() == null ? "" : request.grade().trim();
399	        if (!GRADES.contains(grade)) throw new InvalidPersonException("A grade is one of A, B or C");
400	        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
401	        if (!gradeFrom.isEmpty()) {
402	            try {
403	                LocalDate.parse(gradeFrom);
404	            } catch (DateTimeParseException e) {
405	                throw new InvalidPersonException("A from-date is a date, yyyy-MM-dd");
406	            }
407	        }
408	        String terms = request.terms() == null ? "" : request.terms().trim();
409	        if (!terms.isEmpty() && !terms.matches("\\d{1,6}")) {
410	            throw new InvalidPersonException("Terms are a whole number of days, 0 or more, or blank");
411	        }
412	        if (!terms.isEmpty()) terms = String.valueOf(Integer.parseInt(terms));
413	        body.set(new PersonRequest(name, grade, request.version(), gradeFrom, terms));
414	    }
415	}
