503	                + " name=" + person.getName() + " grade=" + person.gradeOn(sheet.today())
504	                + (termsEdit.changed() ? " terms=" + (person.getTerms() == null ? "" : person.getTerms()) : ""));
505	    }
506	}
507	package net.officefloor.hq.app.person;
