509	import java.time.LocalDate;
510	import java.util.ArrayList;
511	import java.util.List;
512	
513	/**
514	 * A person, as the screen reads it (their grade the one in force on the sheet's today), with their statement count, and the last statement's due-total
515	 * and date ("" before the first), whether they are retired and the date they are retired from
516	 * ("" when not), whether they have any hold, their holds (in the order added), the ids of the people they name as patrons, and every
517	 * grade they have been given with the date it is from (the first "", from the beginning of time),
518	 * by from-date, and their own terms in days ("" for none).
519	 */
520	public record PersonResponse(String id, String name, String grade, long version, int statementCount,
521	        String statedTotal, String statementDate, boolean retired, String retiredFrom,
522	        boolean held, List<HoldFrom> holds, java.util.List<String> patronIds, List<GradeFrom> grades, String terms) {
523	
524	    /** A hold from a date to a date (yyyy-MM-dd; to "" when open-ended), both inclusive. */
525	    public record HoldFrom(String from, String to) {}
526	
527	    /** A grade in force from a date (yyyy-MM-dd; "" from the beginning of time). */
528	    public record GradeFrom(String from, String grade) {}
529	
530	    /** The person as the screen reads it on the sheet's today: their grade is the one in force on it. */
531	    public static PersonResponse from(Person person, LocalDate today) {
532	        List<GradeFrom> grades = new ArrayList<>();
533	        grades.add(new GradeFrom("", person.getGrade()));
534	        person.getDatedGrades().forEach((from, grade) -> grades.add(new GradeFrom(from.toString(), grade)));
535	        return new PersonResponse(String.valueOf(person.getId()), person.getName(), person.gradeOn(today),
536	                person.getVersion(), person.getStatementCount(),
537	                person.getStatedTotal() == null ? "" : person.getStatedTotal(),
538	                person.getStatementDate() == null ? "" : person.getStatementDate().toString(),
539	                person.isRetired(), person.getRetiredFrom() == null ? "" : person.getRetiredFrom().toString(),
540	                person.isHeld(),
541	                person.getHolds().stream().map((h) -> new HoldFrom(h.from().toString(), h.to() == null ? "" : h.to().toString())).toList(),
542	                person.getPatronIds().stream().map(String::valueOf).toList(), grades,
543	                person.getTerms() == null ? "" : person.getTerms().toString());
544	    }
545	}
