567	package net.officefloor.hq.app.person;
568	
569	import java.sql.Date;
570	import java.sql.PreparedStatement;
571	import java.sql.Statement;
572	import java.time.LocalDate;
573	import java.util.HashMap;
574	import java.util.List;
575	import java.util.Map;
576	import java.util.Objects;
577	import org.springframework.jdbc.core.JdbcTemplate;
578	import org.springframework.jdbc.core.RowMapper;
579	import org.springframework.jdbc.support.GeneratedKeyHolder;
580	import org.springframework.stereotype.Repository;
581	
582	/** The people store, kept per sheet. */
583	@Repository
584	public class PersonRepository {
585	
586	    private static final String COLUMNS = "id, sheet_id, name, grade, terms, version, statement_count, stated_total, statement_date, retired_from, added_on";
587	
588	    private static final RowMapper<Person> ROW = (rs, n) -> {
589	        Person person = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
590	                rs.getString("grade"), rs.getLong("version"));
591	        person.setTerms(rs.getObject("terms", Integer.class));
592	        person.setStatements(rs.getInt("statement_count"), rs.getString("stated_total"),
593	                rs.getObject("statement_date", LocalDate.class));
594	        person.setRetiredFrom(rs.getObject("retired_from", LocalDate.class));
595	        person.setAddedOn(rs.getObject("added_on", LocalDate.class));
596	        return person;
597	    };
598	
599	    private final JdbcTemplate jdbc;
600	
601	    public PersonRepository(JdbcTemplate jdbc) {
602	        this.jdbc = jdbc;
603	    }
604	
605	    /** The sheet's people, in the order they were added. */
606	    public List<Person> findAll(String sheetId) {
607	        List<Person> people = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? ORDER BY id",
608	                ROW, sheetId);
609	        Map<Long, Person> byId = new HashMap<>();
610	        people.forEach((p) -> byId.put(p.getId(), p));
611	        jdbc.query("SELECT person_id, from_date, grade FROM person_grade WHERE sheet_id = ?",
612	                (rs) -> {
613	                    Person person = byId.get(rs.getLong("person_id"));
614	                    if (person != null) person.setGradeFrom(rs.getString("grade"), rs.getObject("from_date", LocalDate.class));
615	                }, sheetId);
616	        jdbc.query("SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY person_id, patron_id",
617	                (rs) -> {
618	                    Person person = byId.get(rs.getLong("person_id"));
619	                    if (person != null) person.getPatronIds().add(rs.getLong("patron_id"));
620	                }, sheetId);
621	        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY id",
622	                (rs) -> {
623	                    Person person = byId.get(rs.getLong("person_id"));
624	                    if (person != null) person.getHolds().add(hold(rs));
625	                }, sheetId);
626	        return people;
627	    }
628	
629	    /** The person with this id on the sheet, or null when there is none. */
630	    public Person find(String sheetId, long id) {
631	        List<Person> found = jdbc.query(
632	                "SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
633	                ROW, sheetId, id);
634	        if (found.isEmpty()) return null;
635	        Person person = found.get(0);
636	        loadGrades(person);
637	        loadHolds(person);
638	        person.getPatronIds().addAll(jdbc.queryForList(
639	                "SELECT patron_id FROM person_patron WHERE sheet_id = ? AND person_id = ? ORDER BY patron_id",
640	                Long.class, sheetId, id));
641	        return person;
642	    }
643	
644	    /** Record {@code patron} as one of the person's patrons. */
645	    public void addPatron(Person person, Person patron) {
646	        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, added_on)"
647	                + " VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
648	                person.getSheetId(), person.getId(), patron.getId(), person.getSheetId());
649	        person.getPatronIds().add(patron.getId());
650	    }
651	
652	    /** The person on the sheet with this name, ignoring case and surrounding spaces, or null when there is none. */
653	    public Person findByName(String sheetId, String name) {
654	        List<Person> found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ?"
655	                + " AND LOWER(TRIM(name)) = LOWER(TRIM(?)) ORDER BY id", ROW, sheetId, name);
656	        if (found.isEmpty()) return null;
657	        loadGrades(found.get(0));
658	        loadHolds(found.get(0));
659	        return found.get(0);
660	    }
661	
662	    private void loadGrades(Person person) {
663	        jdbc.query("SELECT from_date, grade FROM person_grade WHERE sheet_id = ? AND person_id = ?",
664	                (rs) -> {
665	                    person.setGradeFrom(rs.getString("grade"), rs.getObject("from_date", LocalDate.class));
666	                }, person.getSheetId(), person.getId());
667	    }
668	
669	    private void loadHolds(Person person) {
670	        jdbc.query("SELECT from_date, to_date FROM person_hold WHERE sheet_id = ? AND person_id = ? ORDER BY id",
671	                (rs) -> {
672	                    person.getHolds().add(hold(rs));
673	                }, person.getSheetId(), person.getId());
674	    }
675	
676	    private static Hold hold(java.sql.ResultSet rs) throws java.sql.SQLException {
677	        return new Hold(rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class));
678	    }
679	
680	    /** Record the person's dated grades as they hold them now, replacing those stored. */
681	    private void saveGrades(Person person) {
682	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?",
683	                person.getSheetId(), person.getId());
684	        person.getDatedGrades().forEach((from, grade) -> jdbc.update(
685	                "INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
686	                person.getSheetId(), person.getId(), Date.valueOf(from), grade));
687	    }
688	
689	    /** Whether a person other than {@code exceptId} has this name on the sheet, ignoring case. */
690	    public boolean nameTaken(String sheetId, String name, Long exceptId) {
691	        Integer count = jdbc.queryForObject(
692	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND LOWER(TRIM(name)) = LOWER(TRIM(?))"
693	                        + " AND id <> ?",
694	                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
695	        return count != null && count > 0;
696	    }
697	
698	    /**
699	     * Record the person's statements (their count, last due-total and date), leaving the rest as stored.
700	     * The last statement is kept as the one numbered by the count; any numbered after it are dropped.
701	     */
702	    public void saveStatements(Person person) {
703	        Date date = person.getStatementDate() == null ? null : Date.valueOf(person.getStatementDate());
704	        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE id = ? AND sheet_id = ?",
705	                person.getStatementCount(), person.getStatedTotal(), date,
706	                person.getId(), person.getSheetId());
707	        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ? AND seq >= ?",
708	                person.getSheetId(), person.getId(), person.getStatementCount());
709	        if (person.getStatementCount() > 0) {
710	            jdbc.update("INSERT INTO person_statement (sheet_id, person_id, seq, stated_total, statement_date) VALUES (?, ?, ?, ?, ?)",
711	                    person.getSheetId(), person.getId(), person.getStatementCount(), person.getStatedTotal(), date);
712	        }
713	        jdbc.update("INSERT INTO person_statement_history (sheet_id, person_id, statement_count, stated_total, statement_date, set_on)"
714	                + " VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
715	                person.getSheetId(), person.getId(), person.getStatementCount(), person.getStatedTotal(), date,
716	                person.getSheetId());
717	    }
718	
719	    /**
720	     * The person's statement numbered {@code seq} (from 1): its due-total and date, or null when it
721	     * was not kept (taken before statements were kept), or there is none.
722	     */
723	    public StatedFigure findStatement(Person person, int seq) {
724	        List<StatedFigure> found = jdbc.query(
725	                "SELECT stated_total, statement_date FROM person_statement WHERE sheet_id = ? AND person_id = ? AND seq = ?",
726	                (rs, n) -> new StatedFigure(rs.getString("stated_total"), rs.getObject("statement_date", LocalDate.class)),
727	                person.getSheetId(), person.getId(), seq);
728	        return found.isEmpty() ? null : found.get(0);
729	    }
730	
731	    /** Record the date the person is retired from, leaving the rest as stored. */
732	    public void saveRetired(Person person) {
733	        jdbc.update("UPDATE person SET retired_from = ? WHERE id = ? AND sheet_id = ?",
734	                person.getRetiredFrom() == null ? null : Date.valueOf(person.getRetiredFrom()),
735	                person.getId(), person.getSheetId());
736	        jdbc.update("INSERT INTO person_retirement (sheet_id, person_id, from_date, set_on)"
737	                + " VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
738	                person.getSheetId(), person.getId(),
739	                person.getRetiredFrom() == null ? null : Date.valueOf(person.getRetiredFrom()), person.getSheetId());
740	    }
741	
742	    /** Record a new hold on the person, leaving the rest as stored. */
743	    public void addHold(Person person, Hold hold) {
744	        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, made_on)"
745	                + " VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
746	                person.getSheetId(), person.getId(), Date.valueOf(hold.from()),
747	                hold.to() == null ? null : Date.valueOf(hold.to()), person.getSheetId());
748	    }
749	
750	    /**
751	     * Insert a new person (assigning its id) or update an existing one, raising its version. False
752	     * when the stored person is no longer at the version it was loaded at: nothing is written.
753	     */
754	    public boolean save(Person person) {
755	        if (person.getId() != null) {
756	            List<String> storedGrade = jdbc.queryForList("SELECT grade FROM person WHERE id = ? AND sheet_id = ?",
757	                    String.class, person.getId(), person.getSheetId());
758	            List<Integer> storedTerms = jdbc.query("SELECT terms FROM person WHERE id = ? AND sheet_id = ?",
759	                    (rs, n) -> rs.getObject("terms", Integer.class), person.getId(), person.getSheetId());
760	            Map<LocalDate, String> storedDated = new HashMap<>();
761	            jdbc.query("SELECT from_date, grade FROM person_grade WHERE sheet_id = ? AND person_id = ?",
762	                    (rs) -> {
763	                        storedDated.put(rs.getObject("from_date", LocalDate.class), rs.getString("grade"));
764	                    }, person.getSheetId(), person.getId());
765	            int updated = jdbc.update("UPDATE person SET name = ?, grade = ?, terms = ?, version = version + 1"
766	                    + " WHERE id = ? AND sheet_id = ? AND version = ?",
767	                    person.getName(), person.getGrade(), person.getTerms(), person.getId(), person.getSheetId(),
768	                    person.getVersion());
769	            if (updated == 0) return false;
770	            person.setVersion(person.getVersion() + 1);
771	            saveGrades(person);
772	            if (storedGrade.isEmpty() || !storedGrade.get(0).equals(person.getGrade())) {
773	                gradeHistory(person, null, person.getGrade());
774	            }
775	            if (storedTerms.isEmpty() || !Objects.equals(storedTerms.get(0), person.getTerms())) termsHistory(person);
776	            person.getDatedGrades().forEach((from, grade) -> {
777	                if (!grade.equals(storedDated.get(from))) gradeHistory(person, from, grade);
778	            });
779	            return true;
780	        }
781	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
782	        jdbc.update(con -> {
783	            PreparedStatement ps = con.prepareStatement(
784	                    "INSERT INTO person (sheet_id, name, grade, terms, added_on) VALUES (?, ?, ?, ?,"
785	                            + " (SELECT today FROM sheet WHERE id = ?))",
786	                    Statement.RETURN_GENERATED_KEYS);
787	            ps.setString(1, person.getSheetId());
788	            ps.setString(2, person.getName());
789	            ps.setString(3, person.getGrade());
790	            ps.setObject(4, person.getTerms(), java.sql.Types.INTEGER);
791	            ps.setString(5, person.getSheetId());
792	            return ps;
793	        }, keys);
794	        person.setId(keys.getKey().longValue());
795	        person.setAddedOn(jdbc.queryForObject("SELECT added_on FROM person WHERE id = ?", LocalDate.class, person.getId()));
796	        saveGrades(person);
797	        gradeHistory(person, null, person.getGrade());
798	        termsHistory(person);
799	        person.getDatedGrades().forEach((from, grade) -> gradeHistory(person, from, grade));
800	        return true;
801	    }
802	
803	    /** Keeps a grade given to the person (from {@code from}; null: their first grade) in its history, with the sheet's today now. */
804	    private void gradeHistory(Person person, LocalDate from, String grade) {
805	        jdbc.update("INSERT INTO person_grade_history (sheet_id, person_id, from_date, grade, set_on)"
806	                + " VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
807	                person.getSheetId(), person.getId(), from == null ? null : Date.valueOf(from), grade, person.getSheetId());
808	    }
809	
810	    /** Keeps the person's terms (null: none) in their history, with the sheet's today now. */
811	    private void termsHistory(Person person) {
812	        jdbc.update("INSERT INTO person_terms_history (sheet_id, person_id, terms, set_on)"
813	                + " VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
814	                person.getSheetId(), person.getId(), person.getTerms(), person.getSheetId());
815	    }
816	
817	    /**
818	     * The person as they stood at the end of {@code day}: their grades, terms, holds, retirement, statements
819	     * and patrons as given while the sheet's today was on or before it; the rest as they are now.
820	     */
821	    public Person asOf(Person person, LocalDate day) {
822	        Date on = Date.valueOf(day);
823	        String[] first = { person.getGrade() };
824	        Map<LocalDate, String> dated = new HashMap<>();
825	        jdbc.query("SELECT from_date, grade FROM person_grade_history WHERE sheet_id = ? AND person_id = ?"
826	                + " AND set_on <= ? ORDER BY id", (rs) -> {
827	                    LocalDate from = rs.getObject("from_date", LocalDate.class);
828	                    if (from == null) first[0] = rs.getString("grade");
829	                    else dated.put(from, rs.getString("grade"));
830	                }, person.getSheetId(), person.getId(), on);
831	        Person then = new Person(person.getId(), person.getSheetId(), person.getName(), first[0], person.getVersion());
832	        List<Integer> terms = jdbc.query("SELECT terms FROM person_terms_history WHERE sheet_id = ? AND person_id = ?"
833	                + " AND set_on <= ? ORDER BY id DESC LIMIT 1", (rs, n) -> rs.getObject("terms", Integer.class),
834	                person.getSheetId(), person.getId(), on);
835	        then.setTerms(terms.isEmpty() ? null : terms.get(0));
836	        then.setAddedOn(person.getAddedOn());
837	        then.setStatements(0, null, null);
838	        jdbc.query("SELECT statement_count, stated_total, statement_date FROM person_statement_history"
839	                + " WHERE sheet_id = ? AND person_id = ? AND set_on <= ? ORDER BY id DESC LIMIT 1", (rs) -> {
840	                    then.setStatements(rs.getInt("statement_count"), rs.getString("stated_total"),
841	                            rs.getObject("statement_date", LocalDate.class));
842	                }, person.getSheetId(), person.getId(), on);
843	        dated.forEach((from, grade) -> then.setGradeFrom(grade, from));
844	        jdbc.query("SELECT from_date, to_date FROM person_hold WHERE sheet_id = ? AND person_id = ?"
845	                + " AND (made_on IS NULL OR made_on <= ?) ORDER BY id", (rs) -> {
846	                    then.getHolds().add(hold(rs));
847	                }, person.getSheetId(), person.getId(), on);
848	        List<LocalDate> retired = jdbc.query("SELECT from_date FROM person_retirement WHERE sheet_id = ? AND person_id = ?"
849	                + " AND set_on <= ? ORDER BY id DESC LIMIT 1", (rs, n) -> rs.getObject("from_date", LocalDate.class),
850	                person.getSheetId(), person.getId(), on);
851	        then.setRetiredFrom(retired.isEmpty() ? null : retired.get(0));
852	        then.getPatronIds().addAll(jdbc.queryForList("SELECT patron_id FROM person_patron WHERE sheet_id = ?"
853	                + " AND person_id = ? AND (added_on IS NULL OR added_on <= ?) ORDER BY patron_id", Long.class,
854	                person.getSheetId(), person.getId(), on));
855	        return then;
856	    }
857	}
